select id, promo_code, ends_on, ntile(5) over (partition by promo_code order by discount_pct desc, id asc) as discount_pct_bucket, lead(discount_pct, 2, 0) over (partition by channel order by discount_pct asc, id asc) as next_discount_pct, avg(discount_pct) over (partition by channel order by starts_on asc, id asc rows between 6 preceding and current row) as discount_pct_avg_6, ntile(3) over (partition by channel order by discount_pct asc, id asc) as discount_pct_bucket_2 from promotions where channel in ('web', 'store');
